style.css:
body {
    background-color: #EFCEC6 !important;  /* Makes the background pink */
    color: black !important;  /* Keeps text readable */
}
body, div, section, header, footer {
    background-color: #EFCEC6 !important;
    color: black !important;
}

a {
    color: darkred !important;  /* Changes links to dark red */
}

button {
    background-color: #D9AFA6 !important;  /* Softer pink for buttons */
    border: none !important;
    color: white !important;
}

input, textarea {
    background-color: #F7E3DD !important;  /* Light pink for forms */
    border: 1px solid #D9AFA6 !important;
    color: black !important;
}
